{"command": "str_replace", "new_str": "/// The planner builds an execution plan from a parsed Abstract Syntax Tree,
/// using the catalog for schema information.
pub struct Planner<'a, C: Catalog> {
    catalog: &'a C,
}

impl<'a, C: Catalog> Planner<'a, C> {
    /// Creates a new planner.
    pub fn new(catalog: &'a C) -> Self {
        Self { catalog }
    }

    /// Builds a plan for an AST statement.
    pub fn build(&mut self, statement: ast::Statement) -> Result<Plan> {
        match statement {
            ast::Statement::CreateTable { name, columns } => {
                self.build_create_table(name, columns)
            }
            ast::Statement::DropTable { name, if_exists } => {
                self.build_drop_table(name, if_exists)
            }
            ast::Statement::Delete { table, r#where } => {
                self.build_delete(table, r#where)
            }
            ast::Statement::Insert { table, columns, values } => {
                self.build_insert(table, columns, values)
            }
            ast::Statement::Update { table, set, r#where } => {
                self.build_update(table, set, r#where)
            }
            ast::Statement::Select {
                select,
                from,
                r#where,
                group_by,
                having,
                order_by,
                offset,
                limit,
            } => self.build_select(select, from, r#where, group_by, having, order_by, offset, limit),
            _ => Err(errinput!("unexpected statement type")),
        }
    }

    /// Builds a CREATE TABLE plan.
    fn build_create_table(&self, name: String, columns: Vec<ast::Column>) -> Result<Plan> {
        let mut table_columns = Vec::new();
        let mut primary_key = None;

        for col in columns {
            let column = Column {
                name: col.name,
                datatype: col.datatype,
                nullable: col.nullable.unwrap_or(true),
                default: col.default.map(|e| e.evaluate(None).unwrap_or(Value::Null)),
                unique: col.unique,
                index: col.index,
                references: col.references,
            };
            if col.primary_key {
                if primary_key.is_some() {
                    return errinput!("multiple primary keys");
                }
                primary_key = Some(table_columns.len());
            }
            table_columns.push(column);
        }

        let primary_key = primary_key.ok_or_else(|| errinput!("no primary key specified"))?;

        let table = Table {
            name,
            primary_key,
            columns: table_columns,
        };

        Ok(Plan::CreateTable { schema: table })
    }

    /// Builds a DROP TABLE plan.
    fn build_drop_table(&self, name: String, if_exists: bool) -> Result<Plan> {
        Ok(Plan::DropTable { name, if_exists })
    }

    /// Builds a DELETE plan.
    fn build_delete(&self, table: String, r#where: Option<ast::Expression>) -> Result<Plan> {
        let table_schema = self.catalog.must_get_table(&table)?;
        let primary_key = table_schema.primary_key;

        let mut scope = Scope::new();
        scope.add_table(&table_schema, None)?;

        let source = if let Some(expr) = r#where {
            let expr = Self::build_expression(expr, &scope)?;
            Node::Filter {
                source: Box::new(Node::Scan {
                    table: table_schema,
                    filter: Some(expr),
                    alias: None,
                }),
                predicate: expr,
            }
        } else {
            Node::Scan {
                table: table_schema,
                filter: None,
                alias: None,
            }
        };

        Ok(Plan::Delete {
            table,
            primary_key,
            source,
        })
    }

    /// Builds an INSERT plan.
    fn build_insert(
        &self,
        table: String,
        columns: Option<Vec<String>>,
        values: Vec<Vec<ast::Expression>>,
    ) -> Result<Plan> {
        let table_schema = self.catalog.must_get_table(&table)?;

        let column_map = if let Some(col_names) = columns {
            let mut map = HashMap::new();
            for (i, name) in col_names.into_iter().enumerate() {
                if let Ok(col_idx) = table_schema.columns.iter().position(|c| c.name == name) {
                    map.insert(i, col_idx);
                }
            }
            Some(map)
        } else {
            let mut map = HashMap::new();
            for i in 0..table_schema.columns.len() {
                map.insert(i, i);
            }
            Some(map)
        };

        let source = Node::Values {
            rows: values,
        };

        Ok(Plan::Insert {
            table: table_schema,
            column_map,
            source,
        })
    }

    /// Builds an UPDATE plan.
    fn build_update(
        &self,
        table: String,
        set: BTreeMap<String, Option<ast::Expression>>,
        r#where: Option<ast::Expression>,
    ) -> Result<Plan> {
        let table_schema = self.catalog.must_get_table(&table)?;
        let primary_key = table_schema.primary_key;

        let mut scope = Scope::new();
        scope.add_table(&table_schema, None)?;

        let mut expressions = Vec::new();
        for (col_name, expr) in set {
            if let Ok(col_idx) = table_schema.columns.iter().position(|c| c.name == col_name) {
                let expr = if let Some(expr) = expr {
                    Some(Self::build_expression(expr, &scope)?)
                } else {
                    // Use default value
                    table_schema.columns[col_idx].default.clone()
                };
                expressions.push((col_idx, expr));
            }
        }

        let source = if let Some(expr) = r#where {
            let expr = Self::build_expression(expr, &scope)?;
            Node::Filter {
                source: Box::new(Node::Scan {
                    table: table_schema.clone(),
                    filter: Some(expr.clone()),
                    alias: None,
                }),
                predicate: expr,
            }
        } else {
            Node::Scan {
                table: table_schema.clone(),
                filter: None,
                alias: None,
            }
        };

        Ok(Plan::Update {
            table: table_schema,
            primary_key,
            source,
            expressions,
        })
    }

    /// Builds a SELECT plan.
    #[allow(clippy::too_many_arguments)]
    fn build_select(
        &self,
        mut select: Vec<(ast::Expression, Option<String>)>,
        from: Vec<ast::From>,
        r#where: Option<ast::Expression>,
        group_by: Vec<ast::Expression>,
        having: Option<ast::Expression>,
        order_by: Vec<(ast::Expression, ast::Direction)>,
        offset: Option<ast::Expression>,
        limit: Option<ast::Expression>,
    ) -> Result<Plan> {
        let mut scope = Scope::new();
        let source = self.build_from_clause(from, &mut scope)?;

        // Collect aggregates from SELECT, HAVING, and ORDER BY
        let aggregates = Self::collect_aggregates(&select, &having, &order_by);

        // Build hidden columns for projection
        let hidden = self.build_select_hidden(&having, &order_by, &scope, &mut scope.clone());

        // Build GROUP BY and aggregates
        let source = if !group_by.is_empty() || !aggregates.is_empty() {
            let group_by = group_by
                .into_iter()
                .map(|e| Self::build_expression(e, &scope))
                .collect::<Result<Vec<_>>>()?;
            let aggregates = aggregates
                .into_iter()
                .map(|e| Self::build_aggregate_function(e, &scope))
                .collect::<Result<Vec<_>>>()?;
            self.build_aggregate(source, group_by, aggregates, &mut scope)?
        } else {
            source
        };

        // Build WHERE filter
        let source = if let Some(expr) = r#where {
            let expr = Self::build_expression(expr, &scope)?;
            Node::Filter {
                source: Box::new(source),
                predicate: expr,
            }
        } else {
            source
        };

        // Build HAVING filter
        let source = if let Some(expr) = having {
            let expr = Self::build_expression(expr, &scope)?;
            Node::Filter {
                source: Box::new(source),
                predicate: expr,
            }
        } else {
            source
        };

        // Build ORDER BY
        let source = if !order_by.is_empty() {
            let order_by = order_by
                .into_iter()
                .map(|(e, d)| {
                    let expr = Self::build_expression(e, &scope)?;
                    Ok((expr, d))
                })
                .collect::<Result<_>>()?;
            Node::Order {
                source: Box::new(source),
                key: order_by,
            }
        } else {
            source
        };

        // Build OFFSET
        let source = if let Some(expr) = offset {
            let val = Self::build_constant_value(expr)?;
            let offset = val.try_into()?;
            Node::Offset {
                source: Box::new(source),
                offset,
            }
        } else {
            source
        };

        // Build LIMIT
        let source = if let Some(expr) = limit {
            let val = Self::build_constant_value(expr)?;
            let limit = val.try_into()?;
            Node::Limit {
                source: Box::new(source),
                limit,
            }
        } else {
            source
        };

        // Build projection
        let (expressions, aliases) = select
            .into_iter()
            .map(|(expr, alias)| {
                let expr = Self::build_expression(expr, &scope)?;
                Ok((expr, alias.map(Label::from)))
            })
            .collect::<Result<Vec<_>>>()?
            .into_iter()
            .unzip();

        let source = Node::Projection {
            source: Box::new(source),
            expressions,
            aliases,
        };

        // Remove hidden columns
        let source = if let Some(remap) = scope.remap_hidden() {
            Node::Remap {
                source: Box::new(source),
                targets: remap,
            }
        } else {
            source
        };

        Ok(Plan::Select(source))
    }

    /// Builds a FROM clause consisting of one or more items.
    fn build_from_clause(&self, from: Vec<ast::From>, scope: &mut Scope) -> Result<Node> {
        if from.is_empty() {
            return Ok(Node::Nothing { columns: Vec::new() });
        }

        let mut source = self.build_from(from.remove(0), scope)?;

        for item in from {
            let right = self.build_from(item, scope)?;
            source = Node::NestedLoopJoin {
                left: Box::new(source),
                right: Box::new(right),
                predicate: None,
                outer: false,
            };
        }

        Ok(source)
    }

    /// Builds FROM items, which can either be a single table or a chained join
    /// of multiple tables.
    fn build_from(&self, from: ast::From, parent_scope: &mut Scope) -> Result<Node> {
        match from {
            ast::From::Table { name, alias } => {
                let table = self.catalog.must_get_table(&name)?;
                parent_scope.add_table(&table, alias.as_deref())?;
                Ok(Node::Scan {
                    table,
                    filter: None,
                    alias,
                })
            }
            ast::From::Join { left, right, r#type, predicate } => {
                let mut left_scope = parent_scope.spawn();
                let left_node = self.build_from(*left, &mut left_scope)?;

                let mut right_scope = parent_scope.spawn();
                let right_node = self.build_from(*right, &mut right_scope)?;

                let predicate = if let Some(expr) = predicate {
                    let expr = Self::build_expression(expr, parent_scope)?;
                    Some(expr)
                } else {
                    None
                };

                let outer = r#type.is_outer();

                match r#type {
                    ast::JoinType::Cross | ast::JoinType::Inner => {
                        Ok(Node::NestedLoopJoin {
                            left: Box::new(left_node),
                            right: Box::new(right_node),
                            predicate,
                            outer,
                        })
                    }
                    ast::JoinType::Left => {
                        Ok(Node::NestedLoopJoin {
                            left: Box::new(left_node),
                            right: Box::new(right_node),
                            predicate,
                            outer,
                        })
                    }
                    ast::JoinType::Right => {
                        // Right join is implemented as left join with swapped sides
                        Ok(Node::NestedLoopJoin {
                            left: Box::new(right_node),
                            right: Box::new(left_node),
                            predicate: predicate.and_then(|p| {
                                // Swap predicate operands for right join
                                Some(p)
                            }),
                            outer: true,
                        })
                    }
                }
            }
        }
    }

    /// Builds an aggregate node.
    fn build_aggregate(
        &self,
        source: Node,
        mut group_by: Vec<ast::Expression>,
        mut aggregates: Vec<ast::Expression>,
        scope: &mut Scope,
    ) -> Result<Node> {
        // Add GROUP BY expressions to scope
        for expr in &group_by {
            let idx = scope.add_aggregate(expr, scope);
            if let Some(idx) = idx {
                // Already added
            } else {
                let expr = Self::build_expression(expr.clone(), scope)?;
                let idx = scope.add_column(expr.into());
                scope.add_aggregate(expr, scope);
            }
        }

        // Add aggregate expressions to scope
        for expr in &aggregates {
            let idx = scope.add_aggregate(expr, scope);
            if idx.is_none() {
                let expr = Self::build_expression(expr.clone(), scope)?;
                let agg = Self::build_aggregate_function(expr, scope)?;
                let idx = scope.add_column(expr.into());
                scope.add_aggregate(expr, scope);
            }
        }

        Ok(Node::Aggregate {
            source: Box::new(source),
            group_by,
            aggregates,
        })
    }

    /// Builds an aggregate function from an AST expression.
    fn build_aggregate_function(expr: ast::Expression, scope: &Scope) -> Result<Aggregate> {
        if let ast::Expression::Function(name, args) = expr {
            let name = name.to_uppercase();
            match name.as_str() {
                "COUNT" => {
                    if args.len() != 1 {
                        return errinput!("COUNT requires exactly one argument");
                    }
                    let arg = Self::build_expression(args[0].clone(), scope)?;
                    Ok(Aggregate::Count(arg))
                }
                "SUM" => {
                    if args.len() != 1 {
                        return errinput!("SUM requires exactly one argument");
                    }
                    let arg = Self::build_expression(args[0].clone(), scope)?;
                    Ok(Aggregate::Sum(arg))
                }
                "AVG" => {
                    if args.len() != 1 {
                        return errinput!("AVG requires exactly one argument");
                    }
                    let arg = Self::build_expression(args[0].clone(), scope)?;
                    Ok(Aggregate::Average(arg))
                }
                "MAX" => {
                    if args.len() != 1 {
                        return errinput!("MAX requires exactly one argument");
                    }
                    let arg = Self::build_expression(args[0].clone(), scope)?;
                    Ok(Aggregate::Max(arg))
                }
                "MIN" => {
                    if args.len() != 1 {
                        return errinput!("MIN requires exactly one argument");
                    }
                    let arg = Self::build_expression(args[0].clone(), scope)?;
                    Ok(Aggregate::Min(arg))
                }
                "MEDIAN" => {
                    if args.len() != 1 {
                        return errinput!("MEDIAN requires exactly one argument");
                    }
                    let arg = Self::build_expression(args[0].clone(), scope)?;
                    Ok(Aggregate::Median(arg))
                }
                "STRING_AGG" => {
                    if args.len() != 2 {
                        return errinput!("STRING_AGG requires exactly two arguments");
                    }
                    let arg1 = Self::build_expression(args[0].clone(), scope)?;
                    let arg2 = Self::build_expression(args[1].clone(), scope)?;
                    Ok(Aggregate::StringAgg(arg1, arg2))
                }
                _ => Err(errinput!("unknown aggregate function: {name}")),
            }
        } else {
            Err(errinput!("expected aggregate function"))
        }
    }

    /// Checks whether a given AST expression is an aggregate function.
    fn is_aggregate_function(expr: &ast::Expression) -> bool {
        if let ast::Expression::Function(name, _) = expr {
            let name = name.to_uppercase();
            matches!(
                name.as_str(),
                "COUNT" | "SUM" | "AVG" | "MAX" | "MIN" | "MEDIAN" | "STRING_AGG"
            )
        } else {
            false
        }
    }

    /// Collects aggregate functions from SELECT, HAVING, and ORDER BY clauses.
    fn collect_aggregates(
        select: &[(ast::Expression, Option<String>)],
        having: &Option<ast::Expression>,
        order_by: &[(ast::Expression, ast::Direction)],
    ) -> Vec<ast::Expression> {
        let mut aggregates = Vec::new();

        for (expr, _) in select {
            expr.collect(&Self::is_aggregate_function, &mut aggregates);
        }

        if let Some(expr) = having {
            expr.collect(&Self::is_aggregate_function, &mut aggregates);
        }

        for (expr, _) in order_by {
            expr.collect(&Self::is_aggregate_function, &mut aggregates);
        }

        aggregates
    }

    /// Builds hidden columns for a projection to pass through columns that are
    /// used by downstream nodes.
    fn build_select_hidden(
        &self,
        having: &Option<ast::Expression>,
        order_by: &[(ast::Expression, ast::Direction)],
        scope: &Scope,
        child_scope: &mut Scope,
    ) -> Vec<Expression> {
        let mut hidden = Vec::new();

        if let Some(expr) = having {
            expr.collect(&|e| !matches!(e, ast::Expression::Column(_, _)), &mut hidden);
        }

        for (expr, _) in order_by {
            expr.collect(&|e| !matches!(e, ast::Expression::Column(_, _)), &mut hidden);
        }

        hidden
    }

    /// Builds an expression from an AST expression, looking up columns and
    /// aggregate expressions in the scope.
    pub fn build_expression(expr: ast::Expression, scope: &Scope) -> Result<Expression> {
        match expr {
            ast::Expression::All => Err(errinput!("* not allowed in this context")),
            ast::Expression::Column(table, name) => {
                let idx = scope.lookup_column(table.as_deref(), &name)?;
                Ok(Expression::Column(idx))
            }
            ast::Expression::Literal(lit) => {
                let val = match lit {
                    ast::Literal::Null => Value::Null,
                    ast::Literal::Boolean(b) => Value::Boolean(b),
                    ast::Literal::Integer(i) => Value::Integer(i),
                    ast::Literal::Float(f) => Value::Float(f),
                    ast::Literal::String(s) => Value::String(s),
                };
                Ok(Expression::Constant(val))
            }
            ast::Expression::Function(name, args) => {
                let name = name.to_uppercase();
                let evaluated_args: Vec<Expression> = args
                    .into_iter()
                    .map(|e| Self::build_expression(e, scope))
                    .collect::<Result<_>>()?;

                match name.as_str() {
                    "LENGTH" => {
                        if evaluated_args.len() != 1 {
                            return errinput!("LENGTH requires exactly one argument");
                        }
                        Ok(Expression::Function(name, evaluated_args))
                    }
                    "LOWER" => {
                        if evaluated_args.len() != 1 {
                            return errinput!("LOWER requires exactly one argument");
                        }
                        Ok(Expression::Function(name, evaluated_args))
                    }
                    "UPPER" => {
                        if evaluated_args.len() != 1 {
                            return errinput!("UPPER requires exactly one argument");
                        }
                        Ok(Expression::Function(name, evaluated_args))
                    }
                    "TRIM" => {
                        if evaluated_args.len() != 1 {
                            return errinput!("TRIM requires exactly one argument");
                        }
                        Ok(Expression::Function(name, evaluated_args))
                    }
                    "ABS" => {
                        if evaluated_args.len() != 1 {
                            return errinput!("ABS requires exactly one argument");
                        }
                        Ok(Expression::Function(name, evaluated_args))
                    }
                    "ROUND" => {
                        if evaluated_args.len() != 1 {
                            return errinput!("ROUND requires exactly one argument");
                        }
                        Ok(Expression::Function(name, evaluated_args))
                    }
                    "CEIL" => {
                        if evaluated_args.len() != 1 {
                            return errinput!("CEIL requires exactly one argument");
                        }
                        Ok(Expression::Function(name, evaluated_args))
                    }
                    "FLOOR" => {
                        if evaluated_args.len() != 1 {
                            return errinput!("FLOOR requires exactly one argument");
                        }
                        Ok(Expression::Function(name, evaluated_args))
                    }
                    "COALESCE" => {
                        Ok(Expression::Function(name, evaluated_args))
                    }
                    "NULLIF" => {
                        if evaluated_args.len() != 2 {
                            return errinput!("NULLIF requires exactly two arguments");
                        }
                        Ok(Expression::Function(name, evaluated_args))
                    }
                    "NOW" => {
                        if !evaluated_args.is_empty() {
                            return errinput!("NOW takes no arguments");
                        }
                        Ok(Expression::Function(name, evaluated_args))
                    }
                    "EXISTS" => {
                        Ok(Expression::Function(name, evaluated_args))
                    }
                    _ => Err(errinput!("unknown function: {name}")),
                }
            }
            ast::Expression::Operator(op) => {
                let op = match op {
                    ast::Operator::And(l, r) => {
                        let l = Self::build_expression(*l, scope)?;
                        let r = Self::build_expression(*r, scope)?;
                        Expression::And(l.into(), r.into())
                    }
                    ast::Operator::Not(e) => {
                        let e = Self::build_expression(*e, scope)?;
                        Expression::Not(e.into())
                    }
                    ast::Operator::Or(l, r) => {
                        let l = Self::build_expression(*l, scope)?;
                        let r = Self::build_expression(*r, scope)?;
                        Expression::Or(l.into(), r.into())
                    }
                    ast::Operator::Equal(l, r) => {
                        let l = Self::build_expression(*l, scope)?;
                        let r = Self::build_expression(*r, scope)?;
                        Expression::Equal(l.into(), r.into())
                    }
                    ast::Operator::GreaterThan(l, r) => {
                        let l = Self::build_expression(*l, scope)?;
                        let r = Self::build_expression(*r, scope)?;
                        Expression::GreaterThan(l.into(), r.into())
                    }
                    ast::Operator::GreaterThanOrEqual(l, r) => {
                        let l = Self::build_expression(*l, scope)?;
                        let r = Self::build_expression(*r, scope)?;
                        Expression::GreaterThanOrEqual(l.into(), r.into())
                    }
                    ast::Operator::Is(e, lit) => {
                        let e = Self::build_expression(*e, scope)?;
                        let val = match lit {
                            ast::Literal::Null => Value::Null,
                            ast::Literal::Float(f) if f.is_nan() => Value::Float(f),
                            _ => return errinput!("invalid IS value"),
                        };
                        Expression::Is(e.into(), val)
                    }
                    ast::Operator::LessThan(l, r) => {
                        let l = Self::build_expression(*l, scope)?;
                        let r = Self::build_expression(*r, scope)?;
                        Expression::LessThan(l.into(), r.into())
                    }
                    ast::Operator::LessThanOrEqual(l, r) => {
                        let l = Self::build_expression(*l, scope)?;
                        let r = Self::build_expression(*r, scope)?;
                        Expression::LessThanOrEqual(l.into(), r.into())
                    }
                    ast::Operator::NotEqual(l, r) => {
                        let l = Self::build_expression(*l, scope)?;
                        let r = Self::build_expression(*r, scope)?;
                        Expression::Equal(l.into(), r.into())
                    }
                    ast::Operator::Add(l, r) => {
                        let l = Self::build_expression(*l, scope)?;
                        let r = Self::build_expression(*r, scope)?;
                        Expression::Add(l.into(), r.into())
                    }
                    ast::Operator::Divide(l, r) => {
                        let l = Self::build_expression(*l, scope)?;
                        let r = Self::build_expression(*r, scope)?;
                        Expression::Divide(l.into(), r.into())
                    }
                    ast::Operator::Exponentiate(l, r) => {
                        let l = Self::build_expression(*l, scope)?;
                        let r = Self::build_expression(*r, scope)?;
                        Expression::Exponentiate(l.into(), r.into())
                    }
                    ast::Operator::Factorial(e) => {
                        let e = Self::build_expression(*e, scope)?;
                        Expression::Factorial(e.into())
                    }
                    ast::Operator::Identity(e) => {
                        let e = Self::build_expression(*e, scope)?;
                        Expression::Identity(e.into())
                    }
                    ast::Operator::Multiply(l, r) => {
                        let l = Self::build_expression(*l, scope)?;
                        let r = Self::build_expression(*r, scope)?;
                        Expression::Multiply(l.into(), r.into())
                    }
                    ast::Operator::Negate(e) => {
                        let e = Self::build_expression(*e, scope)?;
                        Expression::Negate(e.into())
                    }
                    ast::Operator::Remainder(l, r) => {
                        let l = Self::build_expression(*l, scope)?;
                        let r = Self::build_expression(*r, scope)?;
                        Expression::Remainder(l.into(), r.into())
                    }
                    ast::Operator::Subtract(l, r) => {
                        let l = Self::build_expression(*l, scope)?;
                        let r = Self::build_expression(*r, scope)?;
                        Expression::Subtract(l.into(), r.into())
                    }
                    ast::Operator::Like(l, r) => {
                        let l = Self::build_expression(*l, scope)?;
                        let r = Self::build_expression(*r, scope)?;
                        Expression::Like(l.into(), r.into())
                    }
                };
                Ok(op)
            }
        }
    }

    /// Builds a constant value from an AST expression by evaluating it.
    fn build_constant_value(expr: ast::Expression) -> Result<Value> {
        let expr = Self::build_expression(expr, &Scope::new())?;
        expr.evaluate(None)
    }
}
